--  DDL for Table EVOLUTION_REQUIREMENTS
--------------------------------------------------------
DROP TABLE EVOLUTION_REQUIREMENTS;

  CREATE TABLE "EVOLUTION_REQUIREMENTS" 
   (	"ID" NUMBER CONSTRAINT Pk_evo PRIMARY KEY , 
	"EVOLUTION_ID" NUMBER, 
	"REQUIREMENT_TYPE" VARCHAR2(30 BYTE), 
	"REQUIREMENT_VALUE" VARCHAR2(100 BYTE)
   )  ;
   CREATE SEQUENCE EVOLUTION_REQ_SEQ
START WITH 1
INCREMENT BY 1
NOCACHE;
CREATE OR REPLACE TRIGGER EVOLUTION_REQ_BI
BEFORE INSERT ON EVOLUTION_REQUIREMENTS
FOR EACH ROW
WHEN (NEW.ID IS NULL)
BEGIN
  SELECT EVOLUTION_REQ_SEQ.NEXTVAL
  INTO :NEW.ID
  FROM dual;
END;
/

