--------------------------------------------------------
--  CREATE VIEW FOR POKEMON_MASTER_VIEW
--------------------------------------------------------  
      
CREATE OR REPLACE VIEW POKEMON_MASTER_VIEW AS
WITH ALL_LINKS (parent_id, child_id) AS (
    SELECT FROM_POKEMON_ID, TO_POKEMON_ID FROM POKEMON_EVOLUTIONS
    UNION
    SELECT TO_POKEMON_ID, FROM_POKEMON_ID FROM POKEMON_EVOLUTIONS
),
RECURSIVE_CHAIN (root_id, t_id, lvl) AS (
    SELECT ID, ID, 0 FROM POKEMON
    UNION ALL
    SELECT rc.root_id, al.child_id, rc.lvl + 1
    FROM ALL_LINKS al
    JOIN RECURSIVE_CHAIN rc ON al.parent_id = rc.t_id
    WHERE rc.lvl < 5
),
CLEAN_EVOS AS (
    SELECT DISTINCT 
        rc.root_id, 
        rc.t_id, 
        p.NAME as t_name
    FROM RECURSIVE_CHAIN rc
    JOIN POKEMON p ON rc.t_id = p.ID
    WHERE rc.root_id != rc.t_id
),
AGGREGATED_EVOS AS (
    SELECT 
        root_id,
        '[' || LISTAGG(
            '{"to_id":' || t_id || ',"to_name":"' || REPLACE(t_name, '"', '\"') || '"}',
            ','
        ) WITHIN GROUP (ORDER BY t_id) || ']' AS full_chain
    FROM CLEAN_EVOS
    GROUP BY root_id
),
TYPE_AGG AS (
    SELECT POKEMON_ID, 
           MAX(CASE WHEN rn = 1 THEN TYPE_NAME END) AS TYPE1,
           MAX(CASE WHEN rn = 2 THEN TYPE_NAME END) AS TYPE2
    FROM (
        SELECT pt.POKEMON_ID, t.NAME AS TYPE_NAME, ROW_NUMBER() OVER (PARTITION BY pt.POKEMON_ID ORDER BY t.ID) AS rn
        FROM POKEMON_TYPES pt
        JOIN TYPES t ON pt.TYPE_ID = t.ID
    )
    GROUP BY POKEMON_ID
),
ABILITY_AGG AS (
    SELECT pa.POKEMON_ID, LISTAGG(a.NAME, ', ') WITHIN GROUP (ORDER BY a.NAME) AS ABILITIES
    FROM POKEMON_ABILITIES pa
    JOIN ABILITIES a ON pa.ABILITY_ID = a.ID
    GROUP BY pa.POKEMON_ID
)
SELECT 
    p.ID,
    p.NAME,
    p.DESCRIPTION,
    p.HP,
    p.ATTACK,
    p.DEFENSE,
    p.SP_ATK,
    p.SP_DEF,
    p.SPEED,
    p.IMAGE,
    p.BST,
    p.GENERATION,
    p.LEGENDARY,
    p.FINAL_EVOLUTION,
    p.HEIGHT,
    p.WEIGHT,
    p.BMI,
    p.CATCH_RATE,
    ta.TYPE1,
    ta.TYPE2,
    aa.ABILITIES,
    NVL(ae.full_chain, '[]') AS EVO_DATA_JSON
FROM POKEMON p
LEFT JOIN TYPE_AGG ta ON p.ID = ta.POKEMON_ID
LEFT JOIN ABILITY_AGG aa ON p.ID = aa.POKEMON_ID
LEFT JOIN AGGREGATED_EVOS ae ON p.ID = ae.root_id;

--------------------------------------------------------
--  DDL for View POKEMON DIRECT EVOLUTION
--------------------------------------------------------


CREATE OR REPLACE VIEW POKEMON_DIRECT_EVOLUTIONS_VIEW AS
WITH
FORWARD_EVOS AS (
    SELECT 
        pe.FROM_POKEMON_ID AS pokemon_id,
        '[' || LISTAGG(
            '{"to_id":' || pe.TO_POKEMON_ID || 
            ',"to_name":"' || REPLACE(p.NAME, '"', '\"') || '"' ||
            ',"method":"' || COALESCE(REPLACE(er.REQUIREMENT_TYPE, '"', '\"'), 'Level') || '"' ||
            CASE 
                WHEN er.REQUIREMENT_VALUE IS NOT NULL 
                THEN ',"value":"' || REPLACE(er.REQUIREMENT_VALUE, '"', '\"') || '"'
                ELSE ''
            END ||
            '}', ','
        ) WITHIN GROUP (ORDER BY pe.TO_POKEMON_ID) || ']' AS forward_chain
    FROM POKEMON_EVOLUTIONS pe
    JOIN POKEMON p ON pe.TO_POKEMON_ID = p.ID
    LEFT JOIN EVOLUTION_REQUIREMENTS er ON pe.ID = er.EVOLUTION_ID
    GROUP BY pe.FROM_POKEMON_ID
),
BACKWARD_EVOS AS (
    SELECT 
        pe.TO_POKEMON_ID AS pokemon_id,
        '[' || LISTAGG(
            '{"from_id":' || pe.FROM_POKEMON_ID || 
            ',"from_name":"' || REPLACE(p.NAME, '"', '\"') || '"}', ','
        ) WITHIN GROUP (ORDER BY pe.FROM_POKEMON_ID) || ']' AS backward_chain
    FROM POKEMON_EVOLUTIONS pe
    JOIN POKEMON p ON pe.FROM_POKEMON_ID = p.ID
    GROUP BY pe.TO_POKEMON_ID
),
TYPE_AGG AS (
    SELECT
        POKEMON_ID,
        MAX(CASE WHEN rn = 1 THEN TYPE_NAME END) AS TYPE1,
        MAX(CASE WHEN rn = 2 THEN TYPE_NAME END) AS TYPE2
    FROM (
        SELECT
            pt.POKEMON_ID,
            t.NAME AS TYPE_NAME,
            ROW_NUMBER() OVER (PARTITION BY pt.POKEMON_ID ORDER BY t.ID) rn
        FROM POKEMON_TYPES pt
        JOIN TYPES t ON pt.TYPE_ID = t.ID
    )
    GROUP BY POKEMON_ID
),
ABILITY_AGG AS (
    SELECT
        pa.POKEMON_ID,
        LISTAGG(a.NAME, ', ') WITHIN GROUP (ORDER BY a.NAME) AS ABILITIES
    FROM POKEMON_ABILITIES pa
    JOIN ABILITIES a ON pa.ABILITY_ID = a.ID
    GROUP BY pa.POKEMON_ID
)
SELECT
    p.ID,
    p.NAME,
    p.DESCRIPTION,
    p.HP,
    p.ATTACK,
    p.DEFENSE,
    p.SP_ATK,
    p.SP_DEF,
    p.SPEED,
    p.IMAGE,
    p.BST,
    p.GENERATION,
    p.LEGENDARY,
    p.FINAL_EVOLUTION,
    p.HEIGHT,
    p.WEIGHT,
    p.BMI,
    p.CATCH_RATE,
    ta.TYPE1,
    ta.TYPE2,
    aa.ABILITIES,
    fe.forward_chain AS EVOLUTIONS_JSON,
    be.backward_chain AS PRE_EVOLUTIONS_JSON
FROM POKEMON p
LEFT JOIN TYPE_AGG ta ON p.ID = ta.POKEMON_ID
LEFT JOIN ABILITY_AGG aa ON p.ID = aa.POKEMON_ID
LEFT JOIN FORWARD_EVOS fe ON p.ID = fe.pokemon_id
LEFT JOIN BACKWARD_EVOS be ON p.ID = be.pokemon_id;
